%[text] # Process Quantitative EPMA Maps
%[text] ## Import Data
  %[control:button:6f28]{"position":[1,2]}

clear all; close all; 

addpath('../..');
addpath('../../data');
load batlowK.mat
FL     = {'FontSize',16};
FS     = {'FontSize',12};
Fs     = {'FontSize',10};
TX     = {'Interpreter','Latex'};
TL     = {'TicklabelInterpreter','Latex'};
LW     = {'LineWidth',2};
MS     = {'MarkerSize',10};
UN     = {'Units','inches'};

filename = "VIC09A_B2-2_Oxide_Image_Classify.DAT"; %[control:editfield:86b9]{"position":[12,50]}

opts = delimitedTextImportOptions("NumVariables", 18);

% Specify range and delimiter
opts.DataLines = [3, Inf];
opts.Delimiter = "\t";

% Specify column names and types
opts.VariableNames = ["Var1", "X", "Y", "NX", "NY", "NXY", "SiWT", "AlWT", "CaWT", "TiWT", "KWT", "PWT", "FeWT", "MnWT", "NaWT", "MgWT","OWT", "Total", "VarName18"];
opts.SelectedVariableNames = ["X", "Y", "NX", "NY", "NXY", "SiWT", "AlWT", "CaWT", "TiWT", "KWT", "PWT", "FeWT", "MnWT", "NaWT", "MgWT","OWT", "Total"];
opts.VariableTypes = ["string", "double", "double", "double", "double", "double", "double", "double", "double", "double", "double", "double", "double", "double", "double", "double", "double", "double", "double"];

% Specify file level properties
opts.ExtraColumnsRule = "ignore";
opts.EmptyLineRule = "read";

% Specify variable properties
opts = setvaropts(opts, "Var1", "WhitespaceRule", "preserve");
opts = setvaropts(opts, "Var1", "EmptyFieldRule", "auto");
opts = setvaropts(opts, "VarName18", "TrimNonNumeric", true);
opts = setvaropts(opts, "VarName18", "ThousandsSeparator", ",");

% Import the data
DATtab = readtable(filename, opts);

disp('Data loaded successfully') %[output:6246c912]
%%
%[text] ## Convert data
  %[control:button:7ca6]{"position":[1,2]}

% convert table to array
DATvec = table2array(DATtab);

% extract map dimensions
nx = max(DATvec(:,3));
nz = max(DATvec(:,4));
DATmap = reshape(DATvec,nx,nz,[]);
DATmap = permute(DATmap,[2,1,3]);

X  = DATmap(1,:,1).';
Z  = DATmap(:,1,2);

% sort oxides into standard sequence
%           Si Ti Al Fe Mg Ca  Na K  P  Mn O  Total
OxdInd   = [1, 4, 2, 7, 10, 3, 9, 5, 6, 8, 11, 12];
OxdNames = {'SiO2';'TiO2';'Al2O3';'FeO';'MgO';'CaO';'Na2O';'K2O'; 'P2O5'; 'MnO';'O';'Total'};
nc       = length(OxdInd);
Si = 1; Ti = 2; Al = 3; Fe = 4; Mg = 5; Ca = 6; Na = 7; K = 8; P = 9; Mn = 10; O = 11; Total = 12;
OxdVec = DATvec(:,5+OxdInd); OxdVec0 = OxdVec;
OxdMap = fliplr(DATmap(:,:,5+OxdInd));
OxdLim = {[0 90];[0 5];[0 30];[0 30];[0 30];[0 20];[0 10];[0 5];[0 5];[0 5]}; 

% Load BSE image 
bseFileName = "VIC09A B2-2.tif";  %[control:editfield:386d]{"position":[15,32]}
BSE = imread(bseFileName);
if ndims(BSE) == 3
    BSE = rgb2gray(BSE);
end
BSE_img = double(BSE);
BSE_img = BSE_img - min(BSE_img(:));
BSE_img = BSE_img ./ max(BSE_img(:));
BSE_img = imresize(BSE_img, [nz, nx]);
BSE_img = flipud(BSE_img);

% Build per-pixel master table
PixTab = table;
PixTab.x   = DATvec(:,1);
PixTab.y   = DATvec(:,2);
PixTab.nx  = DATvec(:,3);
PixTab.ny  = DATvec(:,4);
PixTab.nxy = DATvec(:,5);

PixTab.SiO2  = OxdVec(:,Si);
PixTab.TiO2  = OxdVec(:,Ti);
PixTab.Al2O3 = OxdVec(:,Al);
PixTab.FeO   = OxdVec(:,Fe);
PixTab.MgO   = OxdVec(:,Mg);
PixTab.CaO   = OxdVec(:,Ca);
PixTab.Na2O  = OxdVec(:,Na);
PixTab.K2O   = OxdVec(:,K);
PixTab.P2O5  = OxdVec(:,P);
PixTab.MnO   = OxdVec(:,Mn);
PixTab.O     = OxdVec(:,O);
PixTab.Total = OxdVec(:,Total);

PixTab.valid   = false(height(PixTab),1);
PixTab.cluster = zeros(height(PixTab),1);
PixTab.trend   = zeros(height(PixTab),1);
% ========================================

disp('Data converted successfully') %[output:756f30fc]
%%
  %[control:button:79b7]{"position":[1,2]}

% extract valid totals
mintot =95; %[control:slider:8d81]{"position":[9,11]}
maxtot =105; %[control:slider:321b]{"position":[9,12]}

valmap = OxdMap(:,:,Total)>mintot & OxdMap(:,:,Total)<maxtot;
valvec = OxdVec(:,Total)>mintot & OxdVec(:,Total)<maxtot;

PixTab.valid = valvec;

fh1 = figure(1); clf; %[output:96c6e7ff]
set(fh1,UN{:},'Position',[1 1 8 6]); %[output:96c6e7ff]
imagesc(X,Z,OxdMap(:,:,Total).*valmap); axis equal tight; colormap(batlowK); colorbar(TL{:},FS{:});  %[output:96c6e7ff]
clim([mintot,maxtot]); %[output:96c6e7ff]
set(gca,TL{:},Fs{:}) %[output:96c6e7ff]
title('Total [wt\%]',TX{:},FL{:}) %[output:96c6e7ff]
%[text] **Fig. 1:** Analytical totals of major oxide measurments of valid points between set min/max tolerance levels.
%%
%[text] ## Plot major element oxide maps
  %[control:button:1e42]{"position":[1,2]}

fh2 = figure(2); clf; %[output:511c836d]
set(fh2,UN{:},'Position',[1 1 25 13]);   %[output:511c836d]
k  = nc-2;
if     k<=4;  kk = 2; kkk = 2; 
elseif k<=6;  kk = 2; kkk = 3;
elseif k<=8;  kk = 2; kkk = 4;
elseif k<=9;  kk = 3; kkk = 3;
elseif k<=10; kk = 2; kkk = 5;
end

tiledlayout(kk, kkk, 'TileSpacing', 'compact', 'Padding', 'compact'); %[output:511c836d]
ik = 1;

for ikk = 1:kk %[output:group:15c2a4a6]
    for ikkk = 1:kkk
        ax = nexttile; %[output:511c836d]
        imagesc(ax, X, Z, OxdMap(:,:,ik) .* valmap); axis equal tight;
        colormap(ax, batlowK);
        
        % === Color bar  ===
        if strcmp(OxdNames{ik}, 'MnO')
            clim(ax, [0, 1]);
        elseif strcmp(OxdNames{ik}, 'MgO')
            clim(ax, [0, 20]);
        else
            clim(ax, OxdLim{ik});
        end
        set(ax, TL{:}, FS{:});
        
        % === Keep the first panel coordinates + scale bar ===
        if ik == 1
            add_scale_bar(ax, X, Z, 20);    % 20 μm scale bar
        else
            set(ax, 'XTick', [], 'YTick', []);
        end
       
        OxdNames_label={'SiO$_2$','TiO$_2$','Al$_2$O$_3$','FeO$_{\textrm{t}}$','MgO','CaO','Na$_2$O','K$_2$O','P$_2$O$_5$','MnO'};
        title(ax,[OxdNames_label{ik},'[wt\%]'],TX{:},FL{:});  
        colorbar(ax, TL{:}, FS{:});
        ik = ik + 1;
    end
end %[output:group:15c2a4a6]
%[text] **Fig. 2:** Major oxide concentrations; colorbar range cropped to improve readability.
%%
%[text] ## Plot False Colour Images
  %[control:button:48cf]{"position":[1,2]}

sat = 2; %[control:slider:0f11]{"position":[7,8]}

fh3 = figure(3); clf; %[output:9f476fd2]
set(fh3,UN{:},'Position',[1 1 12 6]); %[output:9f476fd2]
tiledlayout(1,3,'TileSpacing','tight','Padding','tight'); %[output:9f476fd2]

ax1 = subplot(1,3,1); %[output:9f476fd2]
RGB = OxdVec(:,[Si,Al,Ti]);
RGB = valvec.*(RGB - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:)))) ./ ((mean(RGB(valvec,:))+sat*std(RGB(valvec,:))) - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:))));
imagesc(X,Z,fliplr(permute(reshape(RGB,nx,nz,[]),[2,1,3]))); axis equal tight; %[output:9f476fd2]
set(ax1,TL{:},FS{:}) %[output:9f476fd2]
title('RGB: SiO$_2$, Al$_2$O$_3$, TiO$_2$',TX{:},FL{:}) %[output:9f476fd2]
add_scale_bar(ax1, X, Z, 20);   % 20 μm scale bar, only on first panel %[output:9f476fd2]

ax2 = subplot(1,3,2); %[output:9f476fd2]
RGB = OxdVec(:,[Fe,Mg,Ca]);
RGB = valvec.*(RGB - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:)))) ./ ((mean(RGB(valvec,:))+sat*std(RGB(valvec,:))) - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:))));
imagesc(X,Z,fliplr(permute(reshape(RGB,nx,nz,[]),[2,1,3]))); axis equal tight; %[output:9f476fd2]
set(ax2,TL{:},FS{:}) %[output:9f476fd2]
title('RGB: FeO, MgO, CaO',TX{:},FL{:}) %[output:9f476fd2]
set(ax2, 'XTick', [], 'YTick', []); %[output:9f476fd2]

ax3 = subplot(1,3,3); %[output:9f476fd2]
RGB = OxdVec(:,[K,Na,Ca]);
RGB = valvec.*(RGB - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:)))) ./ ((mean(RGB(valvec,:))+sat*std(RGB(valvec,:))) - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:))));
imagesc(X,Z,fliplr(permute(reshape(RGB,nx,nz,[]),[2,1,3]))); axis equal tight; %[output:9f476fd2]
set(ax3,TL{:},FS{:}) %[output:9f476fd2]
title('RGB: K$_2$O, Na$_2$O, CaO',TX{:},FL{:}) %[output:9f476fd2]
set(ax3, 'XTick', [], 'YTick', []); %[output:9f476fd2]
%[text] **Fig. 4:** False-colour images of raw oxide data showing images of (left to right) RGB = \[TiO2, SiO2, Al2O3\]; \[FeO, MgO, CaO\]; \[K2O, Na2O, CaO\].
%%
%[text] ## Filter and Scale Data
  %[control:button:7abc]{"position":[1,2]}

smth = 0.4; %[control:slider:35ea]{"position":[8,11]}

for i = 1:k
    MAP = reshape(OxdVec0(:,i).*valvec,nx,nz);
    MAP = imnlmfilt(MAP,'DegreeOfSmoothing',smth);
    OxdVec(:,i) = MAP(:);
end


% normalise data to unit sum for relative intensities
OxdVec(:,1:k)  =  OxdVec(:,1:k)./(sum(OxdVec(:,1:k),2)+1e-32);

% ===========================
PixTab.SiO2  = OxdVec(:,Si);
PixTab.TiO2  = OxdVec(:,Ti);
PixTab.Al2O3 = OxdVec(:,Al);
PixTab.FeO   = OxdVec(:,Fe);
PixTab.MgO   = OxdVec(:,Mg);
PixTab.CaO   = OxdVec(:,Ca);
PixTab.Na2O  = OxdVec(:,Na);
PixTab.K2O   = OxdVec(:,K);
PixTab.P2O5  = OxdVec(:,P);
PixTab.MnO   = OxdVec(:,Mn);
PixTab.O     = OxdVec(:,O);
PixTab.Total = sum(OxdVec(:,1:k),2); 
% ===========================

% plot filtered and rescaled results
fh4 = figure(4); clf; %[output:96ac599f]
set(fh4,UN{:},'Position',[1 1 12 8]); %[output:96ac599f]
tiledlayout(1,3,'TileSpacing','tight','Padding','tight'); %[output:96ac599f]

ax1 = nexttile; %[output:96ac599f]
RGB = OxdVec(:,[Si,Al,Ti]);
RGB = valvec.*(RGB - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:)))) ./ ((mean(RGB(valvec,:))+sat*std(RGB(valvec,:))) - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:))));
imagesc(X,Z,fliplr(permute(reshape(RGB,nx,nz,[]),[2,1,3]))); axis equal tight; %[output:96ac599f]
set(ax1,TL{:},Fs{:}) %[output:96ac599f]
title('RGB: SiO$_2$, Al$_2$O$_3$, TiO$_2$',TX{:},FL{:}) %[output:96ac599f]
add_scale_bar(ax1, X, Z, 20);   % 20 μm scale bar, only on first panel %[output:96ac599f]

ax2 = nexttile; %[output:96ac599f]
RGB = OxdVec(:,[Fe,Mg,Ca]);
RGB = valvec.*(RGB - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:)))) ./ ((mean(RGB(valvec,:))+sat*std(RGB(valvec,:))) - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:))));
imagesc(X,Z,fliplr(permute(reshape(RGB,nx,nz,[]),[2,1,3]))); axis equal tight; %[output:96ac599f]
set(ax2,TL{:},Fs{:}) %[output:96ac599f]
title('RGB: FeO, MgO, CaO',TX{:},FL{:}) %[output:96ac599f]
set(ax2, 'XTick', [], 'YTick', []); %[output:96ac599f]

ax3 = nexttile; %[output:96ac599f]
RGB = OxdVec(:,[K,Na,Ca]);
RGB = valvec.*(RGB - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:)))) ./ ((mean(RGB(valvec,:))+sat*std(RGB(valvec,:))) - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:))));
imagesc(X,Z,fliplr(permute(reshape(RGB,nx,nz,[]),[2,1,3]))); axis equal tight; %[output:96ac599f]
set(ax3,TL{:},Fs{:}) %[output:96ac599f]
title('RGB: K$_2$O, Na$_2$O, CaO',TX{:},FL{:}) %[output:96ac599f]
set(ax3, 'XTick', [], 'YTick', []); %[output:96ac599f]
%[text] **Fig. 5:** False-colour images of filtered and rescaled oxide data showing images of (left to right) RGB = \[TiO2, SiO2, Al2O3\]; \[FeO, MgO, CaO\]; \[K2O, Na2O, CaO\].
%%
%[text] ## Perform Principal Component Analysis
  %[control:button:193e]{"position":[1,2]}

[PC, PA, PV] = pca(OxdVec(valvec,1:k),'Algorithm','svd','Centered','on','VariableWeights','variance');
PC = PC.';
CV = cumsum(PV(1:end-1)./sum(PV(1:end-1))); % Compute cumulative explained variance

% Plot trade-off curve
fh5 = figure(5); clf; %[output:4c9af390]
set(fh5,UN{:},'Position',[1 1 7 5]); %[output:4c9af390]
plot(2:k,CV*100,'k-',2:k,CV*100,'r*',LW{:},MS{:}) %[output:4c9af390]

title('PCA tradeoff',TX{:},FL{:}) %[output:4c9af390]
xlabel('principal components',TX{:},FL{:}) %[output:4c9af390]
ylabel('\% variance',TX{:},FL{:}) %[output:4c9af390]
set(gca,TL{:},FS{:},'Xtick',2:k) %[output:4c9af390]
%[text] **Fig. 6:** Principal component tradeoff curve showing cumulative percentage of variance versus number of principal components retained.
%[text] 
%%
%[text] ## Plot the loadings of components over the map

  %[control:button:1db3]{"position":[1,2]}
p_plot = 9;
Ap_plot = zeros(size(OxdVec,1),p_plot);
Ap_plot(valvec,:) = PA(:,1:p_plot);

fh6 = figure(6); clf; %[output:236ce0eb]
set(fh6,'Units','inches','Position',[1 1 16 20]); %[output:236ce0eb]
Nrow = floor(sqrt(p_plot));
Ncol = ceil(p_plot/Nrow);
tt2 = tiledlayout(Nrow,Ncol,'TileSpacing','tight','Padding','compact'); %[output:236ce0eb]

% Shared colour limit for all PCs, so that PC magnitudes can be compared directly.
% Computed from valid pixels only (invalid pixels are zero and would lower the limit).
cax = prctile(abs(Ap_plot(valvec,:)),95,'all');

for nplt = 1:p_plot %[output:group:084d97ea]
    ax = nexttile; %[output:236ce0eb]
    Api = Ap_plot(:,nplt);
    Api(~valvec) = NaN;                          % hide invalid pixels
    Api = fliplr(reshape(Api,nx,nz).');
    h = imagesc(X,Z,Api);
    set(h,'AlphaData',~isnan(Api));              % invalid pixels transparent
    set(ax,'Color',[1 0.85 0.85]);               % shown in pink
    colormap(ax,gray);
    clim(ax,[-cax cax]);                         % same range for every PC
    axis equal tight;
    set(ax,TL{:})
    colorbar(ax,TL{:},FS{:});
    title(['PC ',int2str(nplt)],FL{:},TX{:})
    if nplt == 1
        add_scale_bar(ax, X, Z, 20);             % 20 um scale bar on first panel only
    else
        set(ax, 'XTick', [], 'YTick', []);
    end
end %[output:group:084d97ea]
%%

p_plot = 9;
Ap_plot = zeros(size(OxdVec,1),p_plot);
Ap_plot(valvec,:) = PA(:,1:p_plot);

fh6 = figure(6); clf; %[output:2af0c129]
set(fh6,'Units','inches','Position',[1 1 16 20]); %[output:2af0c129]
Nrow = floor(sqrt(p_plot));
Ncol = ceil(p_plot/Nrow);
tt2 = tiledlayout(Nrow,Ncol,'TileSpacing','tight','Padding','compact'); %[output:2af0c129]

allvals = Ap_plot(:,1:p_plot);
cax = prctile(abs(allvals(:)),95);

for nplt = 1:p_plot %[output:group:891e1bee]
    ax = nexttile; %[output:2af0c129]
    Api = fliplr(reshape(Ap_plot(:,nplt),nx,nz).');
    imagesc(X,Z,Api);
    colormap(gray);
    clim([-cax cax]);
    axis equal tight;
    set(ax,TL{:})
    colorbar(TL{:},FS{:});
    title(['PC ',int2str(nplt)],FL{:},TX{:})
    
    if nplt == 1
        add_scale_bar(ax, X, Z, 20);   % 20 μm scale bar on first panel only
    else
        set(ax, 'XTick', [], 'YTick', []);
    end
end %[output:group:891e1bee]
%%
%[text] ## Reduce Data Dimensions
  %[control:button:956f]{"position":[1,2]}

p =5; %[control:slider:50e7]{"position":[4,5]}

% reduce data to p principal components
Fp = PC(1:p,:);
Ap = zeros(size(OxdVec,1),p);
Ap(valvec,:) = PA(:,1:p);           % PCA scores    【Ap(:,i) represents the spatial distribution of the i-th principal component】
OxdPC = Ap*Fp + mean(OxdVec(:,1:k).*valvec);
Rp = sum((OxdPC-OxdVec(:,1:k).*valvec).^2,2)./sum((OxdVec(:,1:k).*valvec).^2,2);


% Re-plot trade-off curve with truncation dashed line
fh7 = figure(7); clf; %[output:23819d7f]
set(fh7,UN{:},'Position',[1 1 7 5]); %[output:23819d7f]

plot(2:k, CV*100, '-o', ... %[output:23819d7f]
    'Color', [0.2 0.4 0.8], ... %[output:23819d7f]
    'LineWidth', 2, ... %[output:23819d7f]
    'MarkerSize', 6, ... %[output:23819d7f]
    'MarkerFaceColor', [0.2 0.4 0.8], ... %[output:23819d7f]
    'MarkerEdgeColor', [0.2 0.4 0.8], ... %[output:23819d7f]
    'DisplayName', 'Cumulative variance');        %[output:23819d7f]
hold on; %[output:23819d7f]

xline(5, '--', 'Color', [0.4 0.4 0.4], 'LineWidth', 1.2, 'Alpha', 0.7,'HandleVisibility', 'off');% Truncation dashed line %[output:23819d7f]
plot(5, CV(5-1)*100, 'o', ... %[output:23819d7f]
    'LineStyle', 'none', ...                %[output:23819d7f]
    'MarkerSize', 10, ... %[output:23819d7f]
    'MarkerFaceColor', [0.85 0.33 0.10], ... %[output:23819d7f]
    'MarkerEdgeColor', [0.85 0.33 0.10],... %[output:23819d7f]
    'DisplayName', 'Truncation point'); % Highlight PCp marker %[output:23819d7f]

text(5.15, CV(5-1)*100 - 5, 'Truncation', 'FontSize', 12, 'Color', [0.3 0.3 0.3]); %[output:23819d7f]
hold off; %[output:23819d7f]
xlabel('Number of principal components', TX{:}, FL{:}) %[output:23819d7f]
ylabel('Cumulative explained variance (\%)', TX{:}, FL{:}) %[output:23819d7f]
set(gca, TL{:}, FS{:}, 'XTick', 2:k); %[output:23819d7f]
ylim([40 100]); %[output:23819d7f]
xlim([2 k]); %[output:23819d7f]
grid on; %[output:23819d7f]
set(gca, 'GridLineStyle', ':', 'GridAlpha', 0.3); %[output:23819d7f]
box on; %[output:23819d7f]
legend('Location', 'southeast', 'FontSize', 10, 'Box', 'off');           %[output:23819d7f]
% -----------------
fh8 = figure(8); clf; %[output:185dedff]
set(fh8,UN{:},'Position',[1 1 12 6]); %[output:185dedff]
tiledlayout(1,3,'TileSpacing','tight','Padding','tight'); %[output:185dedff]

ax1 = nexttile; %[output:185dedff]
RGB = OxdPC(:,[Si,Al,Ti]);
RGB = valvec.*(RGB - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:)))) ./ ((mean(RGB(valvec,:))+sat*std(RGB(valvec,:))) - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:))));
imagesc(X,Z,fliplr(permute(reshape(RGB,nx,nz,[]),[2,1,3]))); axis equal tight; %[output:185dedff]
set(ax1,TL{:},Fs{:}) %[output:185dedff]
title('RGB: SiO$_2$, Al$_2$O$_3$, TiO$_2$',TX{:},FL{:}) %[output:185dedff]
add_scale_bar(ax1, X, Z, 20);   % 20 μm scale bar on first panel only %[output:185dedff]

ax2 = nexttile; %[output:185dedff]
RGB = OxdPC(:,[Fe,Mg,Ca]);
RGB = valvec.*(RGB - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:)))) ./ ((mean(RGB(valvec,:))+sat*std(RGB(valvec,:))) - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:))));
imagesc(X,Z,fliplr(permute(reshape(RGB,nx,nz,[]),[2,1,3]))); axis equal tight; %[output:185dedff]
set(ax2,TL{:},Fs{:}) %[output:185dedff]
title('RGB: FeO, MgO, CaO',TX{:},FL{:}) %[output:185dedff]
set(ax2, 'XTick', [], 'YTick', []); %[output:185dedff]

ax3 = nexttile; %[output:185dedff]
RGB = OxdPC(:,[K,Na,Ca]);
RGB = valvec.*(RGB - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:)))) ./ ((mean(RGB(valvec,:))+sat*std(RGB(valvec,:))) - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:))));
imagesc(X,Z,fliplr(permute(reshape(RGB,nx,nz,[]),[2,1,3]))); axis equal tight; %[output:185dedff]
set(ax3,TL{:},Fs{:}) %[output:185dedff]
title('RGB: K$_2$O, Na$_2$O, CaO',TX{:},FL{:}) %[output:185dedff]
set(ax3, 'XTick', [], 'YTick', []); %[output:185dedff]
%[text] **Fig. 7:** False-colour images of reduced data showing images of (left to right) RGB = \[TiO2, SiO2, Al2O3\]; \[FeO, MgO, CaO\]; \[K2O, Na2O, CaO\].
fh9 = figure(9); clf; %[output:3dbe2c74]
set(fh9,UN{:},'Position',[1 1 12 6]); %[output:3dbe2c74]
tiledlayout(1,2,'TileSpacing','tight','Padding','tight'); %[output:3dbe2c74]

ax1 = nexttile; %[output:3dbe2c74]
ic = [1,2,min(3,p)];
RGB = Ap(:,ic);
RGB = valvec.*(RGB - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:)))) ./ ((mean(RGB(valvec,:))+sat*std(RGB(valvec,:))) - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:))));
imagesc(X,Z,fliplr(permute(reshape(RGB,nx,nz,[]),[2,1,3]))); axis equal tight; %[output:3dbe2c74]
set(ax1,TL{:},Fs{:}) %[output:3dbe2c74]
title(['RGB: PC',int2str(ic(1)),', PC',int2str(ic(2)),', PC',int2str(ic(3))],TX{:},FL{:}) %[output:3dbe2c74]
add_scale_bar(ax1, X, Z, 20);   % 20 μm scale bar on first panel only %[output:3dbe2c74]

ax2 = nexttile; %[output:3dbe2c74]
ic = [max(1,p-2),max(2,p-1),max(2,p)];
RGB = Ap(:,ic);
RGB = valvec.*(RGB - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:)))) ./ ((mean(RGB(valvec,:))+sat*std(RGB(valvec,:))) - (mean(RGB(valvec,:))-sat*std(RGB(valvec,:))));
imagesc(X,Z,fliplr(permute(reshape(RGB,nx,nz,[]),[2,1,3]))); axis equal tight; %[output:3dbe2c74]
set(ax2,TL{:},Fs{:}) %[output:3dbe2c74]
title(['RGB: PC',int2str(ic(1)),', PC',int2str(ic(2)),', PC',int2str(ic(3))],TX{:},FL{:}) %[output:3dbe2c74]
set(ax2, 'XTick', [], 'YTick', []); %[output:3dbe2c74]
%%
%[text] ## Perform Clustering Analysis
  %[control:button:81a3]{"position":[1,2]}

c =6; %[control:slider:74ef]{"position":[4,5]}

% perform k-means clustering analysis
opts = statset('Display','final');
rng(15);
[Ic,Fc] = kmeans(Ap(valvec,:),c,'MaxIter',1e3,'Replicates',10,'Options',opts); %[output:56921c29]
Icfull = zeros(size(valvec));
Icfull(valvec,1) = Ic;

% get cluster compositions in oxides
ClstOxdMean = zeros(c,k);
ClstOxdStd = zeros(c,k);
for ic = 1:c
    ClstOxdMean(ic,:) = mean(OxdVec(Icfull==ic,1:k));
    ClstOxdStd(ic,:) = std(OxdVec(Icfull==ic,1:k));
end

% sort clusters for ascending SiO2 content
[~,isort] = sort(ClstOxdMean(:,1),'ascend');
ClstOxdMean = ClstOxdMean(isort,:);
ClstOxdStd  = ClstOxdStd (isort,:);
Icfull_sort = zeros(size(valvec));
for ic = 1:c
    Icfull_sort(Icfull==isort(ic)) = ic;
end
Icfull = Icfull_sort;
PixTab.cluster = Icfull;

%% plot trained model map
ColorClass = batlowK(max(1,min(256,1+round((1:256)/(256/c))*round(256/c))),:);
fh10 = figure(10); clf; %[output:1e997fa8]
set(fh10,'Units','inches','Position',[1 1 10 8]); %[output:1e997fa8]
ax = gca; %[output:1e997fa8]
imagesc(X,Z,fliplr(reshape(Icfull,nx,nz).')); %[output:1e997fa8]
colormap(ColorClass); %[output:1e997fa8]
colorbar(TL{:},FS{:}); %[output:1e997fa8]
axis equal tight; %[output:1e997fa8]
title('Classified model map',FL{:},TX{:}) %[output:1e997fa8]
set(ax,TL{:}) %[output:1e997fa8]
add_scale_bar(ax, X, Z, 20);   % 20 μm scale bar %[output:1e997fa8]

% plot clusters separately
fh11 = figure(11); clf; %[output:8e3f677c]
set(fh11,'Units','inches','Position',[1 1 16 12]); %[output:8e3f677c]
Nrow = floor(sqrt(c+1));
Ncol = ceil((c+1)/Nrow);
tt1 = tiledlayout(Nrow,Ncol,'TileSpacing','tight','Padding','compact'); %[output:8e3f677c]

for nplt = 1:c+1 %[output:group:8c60fb1e]
    ax = nexttile; %[output:8e3f677c]
    imagesc(X,Z,fliplr(reshape(Icfull==(nplt-1),nx,nz).'));
    colormap(gray);
    set(ax,TL{:})
    colorbar(TL{:},FS{:});
    axis equal tight;
    title(['Cluster ',int2str(nplt-1)],FL{:},TX{:})
    
    if nplt == 1
        add_scale_bar(ax, X, Z, 20);   % 20 μm scale bar on first panel only
    else
        set(ax, 'XTick', [], 'YTick', []);
    end
end %[output:group:8c60fb1e]
%[text] Cluster compositions mean ( wt% SiO$\_2$, TiO$\_2$, Al$\_2$O$\_3$, FeO, MgO, CaO, Na$\_2$O, K$\_2$O, P$\_2$O$\_5$, MnO)
disp(ClstOxdMean*100) %[output:12593968]
%[text] Cluster compositions standard deviation ( wt% SiO$\_2$, TiO$\_2$, Al$\_2$O$\_3$, FeO, MgO, CaO, Na$\_2$O, K$\_2$O, P$\_2$O$\_5$, MnO)
disp(ClstOxdStd*100) %[output:04a7e171]
%%
%[text] ## Preparation before end member analysis
% Extract data for cluster [] based on existing clustering results

cluster_label = 2;                      % The cluster label you want to analyse %[control:editfield:69c5]{"position":[17,18]}

% Find the indices of valid data points
valid_indices = find(valvec);                              % Find the positions of all valid data in the original matrix.
    
idx_cluster = (Icfull(valid_indices) == cluster_label);    % select points that belong to cluster ic within the valid subset
valvec_cluster = valid_indices(idx_cluster);               % use absolute indices to extract the data
X_subset_cluster = OxdVec(valvec_cluster, 1:k);            % extract the valid data subset for cluster c. size: nValid_cluster1 × k

PixCluster = PixTab(PixTab.valid & PixTab.cluster == cluster_label, :);
X_subset_cluster1 = table2array(PixCluster(:, {'SiO2','TiO2','Al2O3','FeO','MgO','CaO','Na2O','K2O','P2O5','MnO'}));

% =========================
% Plot Harker-type diagram
% =========================
figure; clf %[output:6ef09424]
set(gcf, 'Units', 'inches', 'Position', [1 1 10 8]); %[output:6ef09424]

% SiO2 index
xIdx = strcmp(OxdNames(1:k), 'SiO2');

% for data searching
yNamesData = {'TiO2','Al2O3','FeO','MgO','CaO','Na2O','K2O','P2O5','MnO'};

% for labels
yNamesLabel = {'TiO_2','Al_2O_3','FeO_t','MgO','CaO','Na_2O','K_2O','P_2O_5','MnO'};

n = numel(yNamesData);
for i = 1:n %[output:group:608a5f97]
    subplot(3,3,i) %[output:6ef09424]
    
    yIdx = strcmp(OxdNames(1:k), yNamesData{i});
    
    scatter(X_subset_cluster(:, xIdx) * 100, ...     % × 100 → wt%
            X_subset_cluster(:, yIdx) * 100, ...     % × 100 → wt%
            8, 'k', 'filled')
    
    xlabel('SiO_2 [wt%]','Interpreter', 'tex')
    ylabel([yNamesLabel{i} ' [wt%]'],'Interpreter', 'tex')
    axis tight
    box on
end %[output:group:608a5f97]
%sgtitle('Cluster 2 - Harker-type diagram', 'Interpreter', 'tex')
%%
%[text] ## GMM-Based Sub-Clustering in the (SiO2, target\_oxide) Plane
% ==================================================================
% Purpose:
%   Within a single k-means cluster, further subdivide the data into
%   n_trends Gaussian components in the raw 2D (SiO2, target_oxide)
%   feature space. Each component is a full-covariance ellipse that
%   captures a region of the data cloud (e.g. dense core vs. scatter).
%
% Inputs expected in the workspace:
%   X_subset_cluster  : [n x m] compositional data for the current cluster
%   OxdNames          : cell array of oxide names matching columns of X
%   k                 : number of oxides in use
%   yNames            : oxides to be plotted on y-axes of Harker diagrams
%   PixTab            : pixel table with .valid, .cluster, .trend columns
%   valvec_cluster    : linear pixel indices belonging to this cluster
%   cluster_label     : integer ID of the current k-means cluster
%   BSE_img, X, Z     : BSE image and its spatial coordinate vectors
%   nx, nz            : image dimensions
%   TX, FL, TL, FS    : formatting cell arrays used across the project
% ==================================================================

%% --- Parameters ---
target_oxide    = 'FeO';     % Oxide (vs SiO2) defining the 2D clustering plane.
                             % Pick the one that best separates the sub-groups visually.
n_trends        = 3;         % Number of Gaussian components to fit.
gmm_replicates  = 100;       % Number of random restarts for GMM (higher = more stable).
gmm_covariance  = 'full';    % 'full' allows arbitrarily oriented ellipses (recommended).

rng(42);                     % Fixed random seed for reproducibility.

%% --- Extract 2D feature space (SiO2 on x-axis, target_oxide on y-axis) ---
xIdx = find(strcmp(OxdNames(1:k), 'SiO2'));
yIdx = find(strcmp(OxdNames(1:k), target_oxide));

X2D = X_subset_cluster(:, [xIdx yIdx]);
n_pts = size(X2D, 1);

% z-score normalisation so both axes contribute equally to the Gaussian fits
X2D_mean = mean(X2D, 1);
X2D_std  = std(X2D, 0, 1);
X2D_norm = (X2D - X2D_mean) ./ X2D_std;

% Colour scheme for the resulting sub-groups
trend_colors = lines(n_trends);

%% --- Fit GMM in the standardised 2D space ---
fprintf('\n=== GMM sub-clustering in (SiO2, %s) space ===\n', target_oxide); %[output:1cd19f4f]

opts = statset('MaxIter', 500);
gmm_model = fitgmdist(X2D_norm, n_trends, ...
                      'CovarianceType', gmm_covariance, ...
                      'RegularizationValue', 1e-4, ...
                      'Replicates', gmm_replicates, ...
                      'Options', opts);

% Assign each point to its most likely Gaussian component
trend_labels = cluster(gmm_model, X2D_norm);

%% --- Reorder labels so Trend 1 = steepest negative slope, etc. ---
% This stabilises the label numbering across runs: it becomes interpretable
% (Trend 1 = most negatively sloped sub-group on the Harker plot).
mean_slope_per_trend = nan(n_trends, 1);
for t = 1:n_trends
    mask = (trend_labels == t);
    if sum(mask) < 2, continue; end
    p_fit = polyfit(X2D(mask, 1), X2D(mask, 2), 1);
    mean_slope_per_trend(t) = p_fit(1);   % slope of the trend on raw axes
end

[~, sort_order] = sort(mean_slope_per_trend);   % ascending: most negative first
relabel = zeros(n_trends, 1);
relabel(sort_order) = 1:n_trends;

labels_new = trend_labels;
for t = 1:n_trends
    labels_new(trend_labels == t) = relabel(t);
end
trend_labels = labels_new;

%% --- Report fitted slopes and counts for each trend ---
fprintf('\n=== Fitted trends ===\n'); %[output:64efc31c]
for t = 1:n_trends %[output:group:4c5cd29e]
    mask = (trend_labels == t);
    if sum(mask) < 2, continue; end
    p_fit = polyfit(X2D(mask, 1), X2D(mask, 2), 1);
    fprintf('  Trend %d: slope = %+.3f,  intercept = %+.3f,  n = %d\n', ... %[output:96cdcaff]
        t, p_fit(1), p_fit(2), sum(mask)); %[output:96cdcaff]
end %[output:group:4c5cd29e]

%% --- Write sub-cluster labels back into PixTab ---
PixCluster_idx = find(PixTab.valid & PixTab.cluster == cluster_label);
PixTab.trend(PixCluster_idx) = trend_labels;

%% --- Main scatter plot: (SiO2, target_oxide) coloured by trend ---
fh12 = figure(12); clf; %[output:58fe35ee]
set(fh12, 'Units', 'inches', 'Position', [1 1 7 5.5]); %[output:58fe35ee]
hold on %[output:58fe35ee]

for t = 1:n_trends
    mask = (trend_labels == t);
    if ~any(mask), continue; end
    scatter(X_subset_cluster(mask, xIdx), ... %[output:58fe35ee]
            X_subset_cluster(mask, yIdx), ... %[output:58fe35ee]
            8, trend_colors(t,:), 'filled', ... %[output:58fe35ee]
            'MarkerFaceAlpha', 0.6); %[output:58fe35ee]
end

% Overlay fitted trend lines (one per sub-group)
for t = 1:n_trends
     mask = (trend_labels == t);
if sum(mask) < 2, continue; end
     p_fit = polyfit(X_subset_cluster(mask, xIdx), ...
     X_subset_cluster(mask, yIdx), 1);
     x_line = linspace(min(X_subset_cluster(mask, xIdx)), ...
     max(X_subset_cluster(mask, xIdx)), 50);
     plot(x_line, polyval(p_fit, x_line), '-', ... %[output:58fe35ee]
    'Color', trend_colors(t,:) * 0.6, 'LineWidth', 2.5); %[output:58fe35ee]
end
xlabel('SiO2', TX{:}, FL{:}); %[output:58fe35ee]
ylabel(target_oxide, TX{:}, FL{:}); %[output:58fe35ee]
title(sprintf('Cluster %d - GMM sub-clusters in (SiO2, %s)', ... %[output:58fe35ee]
 cluster_label, target_oxide), TX{:}, FL{:}); %[output:58fe35ee]
legend(arrayfun(@(t) sprintf('Trend %d (n=%d)', t, sum(trend_labels == t)), ... %[output:58fe35ee]
 1:n_trends, 'UniformOutput', false), 'Location', 'best'); %[output:58fe35ee]
box on; axis tight; %[output:58fe35ee]

%% --- Harker diagrams (9-panel) coloured by trend ---
fh13 = figure(13); clf; %[output:8c8ba0a7]
set(fh13, 'Units', 'inches', 'Position', [1 1 12 10]); %[output:8c8ba0a7]
tlo = tiledlayout(3, 3, 'TileSpacing', 'compact', 'Padding', 'compact'); %[output:8c8ba0a7]

for i = 1:numel(yNamesData)
    nexttile; %[output:8c8ba0a7]
    yCol = find(strcmp(OxdNames(1:k), yNamesData{i}));
    hold on
    for it = 1:n_trends
        mask = (trend_labels == it);
        if ~any(mask), continue; end
        scatter(X_subset_cluster(mask, xIdx)*100, ...
                X_subset_cluster(mask, yCol)*100, ...
                8, trend_colors(it,:), 'filled', ...
                'MarkerFaceAlpha', 0.6, ...
                'DisplayName', sprintf('Sub-cluster %d', it));
    end
    hold off
    
    set(gca, 'FontSize', 13, 'LineWidth', 1.5);
    
    if i >= numel(yNamesData) - 2
        xlabel('SiO_2 [wt%]', 'FontSize', 16);
    else
        set(gca, 'XTickLabel', []);
    end
    ylabel([yNamesLabel{i} ' [wt%]'], 'FontSize', 16);
    axis tight; box on;
    
    if i == 3
        legend('Location', 'best', 'FontSize', 9);
    end
end

title(tlo, sprintf('', ... %[output:group:6f24742d] %[output:8c8ba0a7]
    cluster_label), TX{:}, FL{:}); %[output:group:6f24742d] %[output:8c8ba0a7]

%% --- BSE underlay: trends overlaid on the back-scattered electron image ---
% Build a 2D map of sub-cluster labels
trendMap = zeros(nx * nz, 1);
trendMap(valvec_cluster) = trend_labels;
trendMap = fliplr(reshape(trendMap, nx, nz).');   % reshape + flip to match BSE orientation

fh14 = figure(14); set(fh14,'Units','inches','Position',[1 1 8 6]); clf; %[output:975a4513]

BSE_rot = fliplr(rot90(BSE_img, 2));              % same orientation transform as trendMap
imagesc(X, Z, BSE_rot); %[output:975a4513]
colormap(gca, gray(256)); %[output:975a4513]
axis equal tight; %[output:975a4513]
hold on %[output:975a4513]

% Build a transparent RGB overlay, one colour per trend
trendRGB = zeros(size(trendMap, 1), size(trendMap, 2), 3);
trendA   = zeros(size(trendMap));
for t = 1:n_trends
    mask = (trendMap == t);
    for ch = 1:3
        layer = trendRGB(:, :, ch);
        layer(mask) = trend_colors(t, ch);
        trendRGB(:, :, ch) = layer;
    end
    trendA(mask) = 0.8;                           % alpha (transparency) for coloured pixels
end
ih = image(X, Z, trendRGB); %[output:975a4513]
set(ih, 'AlphaData', trendA); %[output:975a4513]

% Dummy scatter objects just to build the legend
hLeg = gobjects(n_trends, 1);
for t = 1:n_trends
    n_t = sum(trend_labels == t);
    hLeg(t) = scatter(NaN, NaN, 40, trend_colors(t,:), 'filled', ... %[output:975a4513]
                      'DisplayName', sprintf('Sub-cluster %d (n=%d)', t, n_t)); %[output:975a4513]
end
legend(hLeg, 'Location', 'bestoutside'); %[output:975a4513]
title(sprintf('Cluster %d - GMM trends on BSE', cluster_label), TX{:}, FL{:}); %[output:975a4513]
%%
%[text] ## Run PCA of new selected cluster before end member analysis
% Select pixels belonging to one or multiple sub-clusters
sub_cluster_idx = [2];                                        %[control:editfield:8ba2]{"position":[20,21]}
mask_sub = ismember(trend_labels, sub_cluster_idx);             
valvec_new_cluster = valvec_cluster(mask_sub);                                      

X_subset_new_cluster = OxdVec(valvec_new_cluster, 1:k); 

% ===================================================================
%  Show X_subset_new_cluster Data (converted to wt%)
% ===================================================================

X_plot = X_subset_new_cluster * 100;
OxdNames_sh = OxdNames(1:10);
col_pts   = [0 0 0];
mk_pts    = 'o';
sz_pts    = 15;
alpha_pts = 0.5;
[nSamples, nOxd] = size(X_plot);

fh15 = figure(15); clf; %[output:9d8481d6]
set(fh15, 'Position', [50, 50, 1300, 900], 'Color', 'w'); %[output:9d8481d6]
tlo = tiledlayout(3, 3, 'TileSpacing', 'tight', 'Padding', 'compact'); %[output:9d8481d6]

for pp = 2:nOxd %[output:group:1609dee6]
    nexttile; %[output:9d8481d6]
    hold on; box on;

    scatter(X_plot(:, 1), X_plot(:, pp), ...
        sz_pts, mk_pts, ...
        'MarkerFaceColor', col_pts, ...
        'MarkerEdgeColor', col_pts, ...
        'MarkerFaceAlpha', alpha_pts, ...
        'MarkerEdgeAlpha', alpha_pts);

    % Axes
    if pp >= nOxd - 2
        xlabel([OxdNames_sh{1}, ' [wt%]'], 'FontSize', 11);
    else
        set(gca, 'XTickLabel', []);
    end
    ylabel([OxdNames_sh{pp}, ' [wt%]'], 'FontSize', 11);
    set(gca, 'FontSize', 10);
end %[output:group:1609dee6]
mean_subcomp = mean(X_subset_new_cluster, 1);   
disp(mean_subcomp *100) %[output:47644f9b]

%% perform principal component analysis
[PCc, PAc, PVc] = pca((X_subset_new_cluster),'Algorithm','svd','Centered','on','VariableWeights','variance');
PCc = PCc.';
CVc = cumsum(PVc(1:end-1)./sum(PVc(1:end-1)));

% plot tradeoff curve
fh16 = figure(16); clf; %[output:9f92d884]
set(fh16,UN{:},'Position',[1 1 7 5]); %[output:9f92d884]

plot(2:k,CVc*100,'k-',2:k,CVc*100,'r*',LW{:},MS{:}) %[output:9f92d884]
title('PCA tradeoff',TX{:},FL{:}) %[output:9f92d884]
xlabel('principal components',TX{:},FL{:}) %[output:9f92d884]
ylabel('\% variance',TX{:},FL{:}) %[output:9f92d884]
set(gca,TL{:},FS{:},'Xtick',2:k) %[output:9f92d884]
%%
%[text] ## Reduce Data Dimensions of new cluster
  %[control:button:396f]{"position":[1,2]}

p =1; %[control:slider:36c5]{"position":[4,5]}

% reduce data to p principal components
Fpc = PCc(1:p,:);
Apc = PAc(:,1:p);                                    % APc no longer needs to create a zero matrix first, because X_subset_cluster already contains the valid data within the cluster.
OxdPCc = Apc*Fpc + mean(X_subset_new_cluster,1);     % PCA-reconstructed data, obtained after reducing the dimensionality and projecting back to the original space.
Rpc = sum((OxdPCc-X_subset_new_cluster).^2,2)./sum((X_subset_new_cluster.*valvec_new_cluster).^2,2);  
%%
%[text] ## End member analysis on the cluster compositions
  %[control:button:846c]{"position":[1,2]}

addpath('../../unmix/src/');
mX_cluster = mean(OxdVec(valvec_new_cluster, 1:k), 1);

% end member = p + 1
DGN = struct();
DGN.p = p + 1;

% Extract the valid data subset for cluster c 
[m_cluster, n_cluster] = size(X_subset_new_cluster);
DGN.m = m_cluster;  % points number

% Configure the DGN structure
DGN.Ii = (1:size(Apc,1)).';
DGN.Ir = [];
DGN.meanX = mX_cluster;
DGN.PC = PCc;                                 

% internal end-members
[FInt, FIntp, AInt, DGN] = maximise(Apc, DGN);

% external end-members
[FExt, FExtp, AExt, DGN] = minimise(Apc, FInt, DGN); %[output:5cc264fe]
% 在 minimise 函数最后加一行
disp('FExt values:'); disp(FExt); %[output:8c56f53e]
%%
%[text] ## Visualizing the results
  %[control:button:4cc3]{"position":[1,2]}

OxdNames_subset = OxdNames(1:n_cluster);
DGN.Ii = (1:DGN.m).';
DGN.Ir = [];
DGN.fn = 1;
vstype = 'sct';  % scatter plot    the data cloud on like a Harker diagram 
%%
% Plot Fe-rich droplet data with Si-rich melt projection
DGN.fh(DGN.fn) = visualise(DGN.fn,{X_subset_new_cluster},{'Fe-rich droplet pixels'},'',DGN,OxdNames_subset); %[output:766fa20c]
DGN.fn = DGN.fn+1;
sgtitle(''); %[output:766fa20c]

SiRichMelt = ClstOxdMean(6,:);
nn = length(OxdNames_subset);
for pp = 2:nn %[output:group:66149891]
    subplot(ceil(sqrt(nn-1)), ceil((nn-1)/ceil(sqrt(nn-1))), pp-1); %[output:766fa20c]
    hold on;
    
    % Fit and extend trend line towards Si-rich melt
    x = X_subset_new_cluster(:,1);
    y = X_subset_new_cluster(:,pp);
    P = polyfit(x, y, 1);
    x_ext = linspace(min(x), SiRichMelt(1)*1.05, 100);
    y_ext = polyval(P, x_ext);
    plot(x_ext, y_ext, '--', 'Color', [0.5 0.5 0.5], 'LineWidth', 1.2);
    
    % Plot Si-rich melt mean
    plot(SiRichMelt(1), SiRichMelt(pp), 'd', 'MarkerSize', 8, ...
        'MarkerFaceColor', [0.8 0.2 0.2], 'MarkerEdgeColor', 'k', 'LineWidth', 1.5);
    
    % Convert tick labels to wt%
    xticks_val = get(gca, 'XTick');
    set(gca, 'XTickLabel', arrayfun(@(v) sprintf('%.0f', v*100), xticks_val, 'UniformOutput', false));
    yticks_val = get(gca, 'YTick');
    set(gca, 'YTickLabel', arrayfun(@(v) sprintf('%.1f', v*100), yticks_val, 'UniformOutput', false));
 
    % for labels
    xlabel([OxdNames_subset{1}, ' [wt%]'], 'FontSize', 14);
    ylabel([OxdNames_subset{pp}, ' [wt%]'], 'FontSize', 14);
    
    if pp == 2
        legend({'Fe-rich droplet pixels', 'Extrapolated trend', 'Si-rich melt mean'}, ...
            'FontSize', 8, 'Location', 'best', 'Box', 'on');
    end
end %[output:group:66149891]
DGN.fh(DGN.fn) = visualise(DGN.fn, ... %[output:group:07d9bd69] %[output:1676b738]
    {X_subset_new_cluster*100, OxdPCc*100, FInt*100, FExt*100}, ... %[output:1676b738]
    {'orig. data', 'PCA fit', 'internal EMs', 'external EMs'}, ... %[output:1676b738]
    ['Fitted model with ', num2str(DGN.p), ' internal and external EMs'], ... %[output:1676b738]
    DGN, OxdNames_subset); %[output:group:07d9bd69] %[output:1676b738]
DGN.fn = DGN.fn + 1;
%[text] Cluster internal end member compositions (wt% SiO$\_2$, TiO$\_2$, Al$\_2$O$\_3$, FeO, MgO, CaO, Na$\_2$O, K$\_2$O, P$\_2$O$\_5$, MnO) 
disp(FInt*100)   %[output:6bbf431e]
%[text] Cluster external end member compositions (wt% SiO$\_2$, TiO$\_2$, Al$\_2$O$\_3$, FeO, MgO, CaO, Na$\_2$O, K$\_2$O, P$\_2$O$\_5$, MnO) 
disp(FExt*100) %[output:95111828]
%%
%[text] ## End-member mixing mapping
  %[control:button:1d4a]{"position":[1,2]}

n_endmembers = size(AInt, 2);

% Define RGB groups manually or automatically
rgb_groups = { [1, 2, min(3,n_endmembers)],[max(1,n_endmembers-2), max(2,n_endmembers-1), max(3,n_endmembers)]};

% =============================
% 1. Convert grayscale BSE to RGB background

BSE_rgb = repmat(BSE_img, [1 1 3]);       

fh17 = figure(17); clf; %[output:117589fd]
set(fh17, 'Units', 'inches', 'Position', [1 1 10 8]); %[output:117589fd]

for ig = 1:numel(rgb_groups) %[output:group:28bad835]

    em_idx = rgb_groups{ig};
    if any(em_idx > n_endmembers)
        warning('Skipping group %d because some end-member indices exceed n_endmembers.', ig); %[output:472a7d83]
        continue;
    end
% =============================
% 2. Build RGB mixing image

A_rgb = AInt(:, em_idx);

if max(A_rgb(:)) > 1
    A_rgb = A_rgb / 100;                  % If abundances are percentages (0-100), convert to 0-1
end

A_rgb(A_rgb < 0) = 0;                     % Clip to [0,1]
A_rgb(A_rgb > 1) = 1;

row_sum = sum(A_rgb, 2);                  % Normalize within selected 3 end-members
row_sum(row_sum == 0) = 1;
A_rgb = A_rgb ./ row_sum;

RGB_full = nan(nx*nz, 3);                 % Remap back to full grid
RGB_full(valvec_new_cluster, :) = A_rgb;
RGB_full(~valvec, :) = nan;

R = fliplr(reshape(RGB_full(:,1), nx, nz).');
G = fliplr(reshape(RGB_full(:,2), nx, nz).');
B = fliplr(reshape(RGB_full(:,3), nx, nz).');

RGB_image = cat(3, R, G, B);
RGB_image = RGB_image .^ 0.8;
mask_valid_rgb = ~any(isnan(RGB_image), 3);% Define valid area 

% invalid area set to 0 (don't set to white)
for k1 = 1:3
    tmp = RGB_image(:,:,k1);
    tmp(~mask_valid_rgb) = 0;
    RGB_image(:,:,k1) = tmp;
end

alpha_overlay = 1. * double(mask_valid_rgb);% transparency

% 3. Combine RGS and BSE base image
% plot BSE base image
subplot(1,2,ig) %[output:117589fd]
hBSE = image(X, Z, BSE_rgb);
set(hBSE, 'AlphaData', 1);   
set(gca, 'YDir', 'normal');
axis equal tight;
hold on;

% Overlay RGB mixing image
hRGB = image(X, Z, flipud(RGB_image));
set(hRGB, 'AlphaData', flipud(alpha_overlay));

title({'End-member Spatial Map over BSE', ...
       sprintf('R = EM-%d, G = EM-%d, B = EM-%d', em_idx(1), em_idx(2), em_idx(3))}, ...
       FL{:}, TX{:});
set(gca, TL{:});

end %[output:group:28bad835]

